function collapseRanges(nums: number[]): string[] {
  const out: string[] = [];
  let i = 0;
  while (i < nums.length) {
    let j = i;
    while (j + 1 < nums.length && nums[j + 1] === nums[j] + 1) j++;
    out.push(i === j ? String(nums[i]) : nums[i] + ".." + nums[j]);
    i = j + 1;
  }
  return out;
}

